bool Runtime::start(){view_=fixture;view_.revision=1;view_.canvasRevision=1;return true;}
bool Runtime::request(Command c){commands.push_back(c);switch(c.action){case Action::Bind:view_.context=c.context;view_.consent=false;break;case Action::Question:view_.question=c.text;break;case Action::Correction:view_.correctedText=c.text;break;case Action::Consent:view_.consent=c.flag;break;case Action::Interpret:view_.interpretation="correctable";view_.correctedText="Recognized";break;case Action::Send:view_.active=true;view_.nextWriting=true;view_.request="00000000-0000-0000-0000-000000000011";view_.answer=sendAnswer;break;case Action::NextTurn:view_.nextWriting=true;break;case Action::Stop:view_.active=false;break;case Action::Retry:view_.request="00000000-0000-0000-0000-000000000012";break;case Action::Clear:view_.handwriting={};++view_.canvasRevision;break;default:break;}++view_.revision;view_.saved=true;return true;}
View Runtime::view()const{auto v=view_;v.answer+=streamAppend;v.revision+=streamRevision;v.busy|=forceBusy;if(completeResponse){v.active=false;v.answerComplete=true;++v.revision;}return v;}unsigned Runtime::unsaved()const noexcept{return canvas_.unsaved()+unsigned(forceCommitPending);}bool Runtime::failed()const noexcept{return failedFinish||canvas_.failed();}bool Runtime::finish(unsigned)noexcept{canvas_.stop();return !failedFinish&&!canvas_.unsaved();}bool Runtime::drained()const noexcept{return true;}
